INSERT INTO `events` (`id`, `title`, `description`, `start_date`, `end_date`, `start_time`, `event_registra`) VALUES
(64, 'Dolorum ullam ut aperiam eligendi.', 'Totam sunt hic dolorum. Quia sed cumque rerum aut alias et omnis impedit. Eligendi molestiae sit et est.', '2021-03-02', '2021-02-21', '21:12:00', 'Neal'),
(84, 'Recusandae quae mollitia est quo tempora.', 'Mollitia aut eveniet mollitia quia. Et enim nulla qui molestias sed rerum. Consectetur id ullam qui necessitatibus possimus numquam.', '2021-03-03', '2020-12-02', '12:10:00', 'Keith'),
(247, 'Ipsa rerum quibusdam aliquid.', 'Necessitatibus maiores error doloremque eveniet. Magnam et eaque at ad. Soluta possimus delectus voluptate nobis exercitationem.', '2021-03-04', '2021-01-21', '10:09:00', 'Walker'),
(433, 'Fuga vitae et voluptas tempore non.', 'Recusandae nobis fugit repellat et. Culpa itaque aut itaque quis. Rem fugiat sint repudiandae beatae. Incidunt distinctio earum reprehenderit.', '2021-03-07', '2020-10-21', '12:07:00', 'Jess'),
(441, 'Hic iusto reiciendis.', 'Ipsum vitae impedit libero natus sed. Nisi praesentium sint perferendis odit porro. Exercitationem suscipit quis hic consequuntur fugiat.', '2021-03-05', '2020-05-04', '02:10:00', 'Lorine'),
(442, 'Nobis accusamus debitis error.', 'Ex velit tenetur velit eos. Earum quaerat perspiciatis et ad sed. Enim libero quis aut quo.', '2021-02-28', '2020-07-20', '04:10:00', 'Karley'),
(547, 'Repudiandae alias ab qui voluptatem.', 'Reprehenderit aliquam sed dolorem. Sit porro vitae vel. Quidem sint molestias consequatur aliquam. Quia aliquid porro maiores.', '2021-03-03', '2020-05-31', '08:35:00', 'Lindsey'),
(573, 'Maxime dolor sunt placeat asperiores.', 'Ad et incidunt ut. Harum error repellat officiis ipsum quaerat. Dolorem ea tempore et nihil. Ut dolorum et natus sed voluptas.', '2021-03-07', '2021-01-29', '14:27:00', 'Kole'),
(583, 'Aut nihil perferendis dolorem.', 'A quis omnis sint harum nam quasi animi sed. Odio odio quo facilis facilis amet sit. Dolorem corporis placeat at ex perferendis atque culpa.', '2021-03-07', '2021-03-01', '06:47:00', 'Vilma'),
(707, 'Officiis doloribus et et architecto.', 'Iste eligendi fuga repellat est. Debitis sit quos tempore excepturi dolores occaecati. Non maxime omnis accusamus alias necessitatibus voluptates.', '2021-03-03', '2020-03-10', '03:39:00', 'Juston'),
(848, 'Assumenda cupiditate commodi facilis sit.', 'Laudantium excepturi dolore esse. Et omnis tenetur at expedita. Veritatis dolores aut quia. Ullam eos officiis molestias.', '2021-02-28', '2020-11-13', '04:46:00', 'Joanny');
