CREATE DEFINER=`Dallington`@`localhost` PROCEDURE `MarkEmailAsRun` (IN `useremail` VARCHAR(255), IN `createdAt` VARCHAR(255))  BEGIN

 IF EXISTS (SELECT 1 FROM queued_emails WHERE email=useremail and created_at=createdAt) THEN
   UPDATE queued_emails SET run=1 WHERE
   email=useremail and created_at=createdAt;
   SELECT 1;
  ELSE
  SELECT 0;
 END IF;
 END$$

CREATE DEFINER=`Dallington`@`localhost` PROCEDURE `MarkSMSAsQueued` (IN `sendertelno` VARCHAR(255), IN `receivertelno` VARCHAR(255), IN `createdAt` VARCHAR(255))  BEGIN
 IF EXISTS (SELECT 1 FROM queued_emails WHERE email=useremail and created_at=createdAt) THEN
	  UPDATE queued_sms SET queued=1, sent=1 WHERE    sender_telno=sendertelno and receiver_telno=receivertelno and created_at=createdAt;
      SELECT 1;
ELSE
 SELECT 0;
END IF;
END$$

