CREATE ALGORITHM=UNDEFINED DEFINER=`Dallington`@`localhost` SQL SECURITY DEFINER VIEW `top_cashiers`  AS SELECT `sales`.`cashier` AS `cashier`, sum(`sales`.`amount`) AS `totalsales`, round(sum(`sales`.`amount`) * 100 / (select sum(`monthlysales`.`TotalSales`) from `monthlysales`),2) AS `percent` FROM `sales` GROUP BY `sales`.`cashier` ORDER BY sum(`sales`.`amount`) DESC ;

