DROP TABLE IF EXISTS `top_customers`;

CREATE ALGORITHM=UNDEFINED DEFINER=`Dallington`@`localhost` SQL SECURITY DEFINER VIEW `top_customers`  AS SELECT `sales`.`customer` AS `customer`, sum(`sales`.`amount`) AS `volumeofsales`, round(sum(`sales`.`amount`) * 100 / (select sum(`monthlysales`.`TotalSales`) from `monthlysales`),2) AS `percent` FROM `sales` GROUP BY `sales`.`customer` ORDER BY sum(`sales`.`amount`) DESC LIMIT 0, 10 ;

